B.OF={"#":0,"app:start":1,"~":2,"|":3,"'":4,"app:shift":5,"app:alpha":6,"app:tab":7,"app:menue":8,"menue:hauptmenue":9,"menue:bibliotheken":10,"menue:ok":11,"menue:programm":12,"app:hilfe":13,"app:cursorkreuz":14,"app:maximieren":15,"app:enter":16,"app:loeschen":17,"app:umbruch":18,"app:eingabe":19,"app:cl":20,"app:stack":21,"app:funktionen":22,"app:variablen":23}
B.a1N=new A.aq("Shift+MEN\xdc","Hilfe an; dann eine Taste oder ein Element der Anzeige antippen","",B.m,"","","")
