B.Ik=new A.bw("app:enter","ENTER",B.Kv,"Im Men\xfc hei\xdft die Taste OK, siehe [[menue:ok]]. Siehe auch [[ ]], [[_]], [[app:umbruch]].",B.B)
B.a26=new A.aq("\u232b","nimmt das zuletzt eingegebene Zeichen zur\xfcck","",B.m,"","","")
B.a2w=new A.aq("Shift+C","l\xf6scht den Stack","",B.m,"","","")
B.a1O=new A.aq("Shift+'C","l\xf6scht Stack und Tags","",B.m,"","","")
